import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import os

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Clean columns if needed
df.columns = df.columns.str.strip()

# Helper for base64 images
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Set aesthetic style
sns.set_theme(style="whitegrid", palette="muted")
color_palette = {'Fiction': '#4C72B0', 'Non Fiction': '#DD8452'}

# 1. Market Overview
total_books = len(df)
genre_split = df['Genre'].value_counts()
avg_price = df['Price'].mean()
avg_rating = df['User Rating'].mean()
avg_reviews = df['Reviews'].mean()

# 2. Correlation
corr_coef = df['Price'].corr(df['User Rating'])

# Scatter Plot
fig1, ax1 = plt.subplots(figsize=(8, 6))
sns.scatterplot(data=df, x='Price', y='User Rating', hue='Genre', alpha=0.6, ax=ax1, palette=color_palette)
ax1.set_title("Price vs. User Rating (2009-2019)", fontsize=14, fontweight='bold')
ax1.set_xlabel("Price ($)", fontsize=12)
ax1.set_ylabel("User Rating", fontsize=12)
plt.tight_layout()
scatter_img = fig_to_base64(fig1)

# 3. Genre Comparison
genre_stats = df.groupby('Genre')[['Price', 'User Rating', 'Reviews']].mean().reset_index()

fig2, axes2 = plt.subplots(1, 3, figsize=(16, 5))
sns.barplot(data=genre_stats, x='Genre', y='Price', ax=axes2[0], palette=color_palette)
axes2[0].set_title("Average Price by Genre", fontsize=12, fontweight='bold')
axes2[0].set_ylabel("Price ($)")
axes2[0].set_xlabel("")

sns.barplot(data=genre_stats, x='Genre', y='User Rating', ax=axes2[1], palette=color_palette)
axes2[1].set_title("Average User Rating by Genre", fontsize=12, fontweight='bold')
axes2[1].set_ylabel("User Rating")
axes2[1].set_xlabel("")
axes2[1].set_ylim(4.0, 5.0)

sns.barplot(data=genre_stats, x='Genre', y='Reviews', ax=axes2[2], palette=color_palette)
axes2[2].set_title("Average Reviews by Genre", fontsize=12, fontweight='bold')
axes2[2].set_ylabel("Review Count")
axes2[2].set_xlabel("")
plt.tight_layout()
genre_comp_img = fig_to_base64(fig2)

# 4. Year-over-Year Trends
yearly_stats = df.groupby(['Year', 'Genre'])[['Price', 'User Rating', 'Reviews']].mean().reset_index()
overall_yearly = df.groupby('Year')[['Price', 'User Rating', 'Reviews']].mean().reset_index()

fig3, axes3 = plt.subplots(3, 1, figsize=(12, 16))
sns.lineplot(data=yearly_stats, x='Year', y='Price', hue='Genre', marker='o', ax=axes3[0], palette=color_palette)
sns.lineplot(data=overall_yearly, x='Year', y='Price', color='black', linestyle='--', label='Overall Avg', ax=axes3[0])
axes3[0].set_title("Average Price Trend (2009-2019)", fontsize=14, fontweight='bold')
axes3[0].set_ylabel("Price ($)")
axes3[0].set_xticks(range(2009, 2020))

sns.lineplot(data=yearly_stats, x='Year', y='User Rating', hue='Genre', marker='o', ax=axes3[1], palette=color_palette)
sns.lineplot(data=overall_yearly, x='Year', y='User Rating', color='black', linestyle='--', label='Overall Avg', ax=axes3[1])
axes3[1].set_title("Average User Rating Trend (2009-2019)", fontsize=14, fontweight='bold')
axes3[1].set_ylabel("User Rating")
axes3[1].set_xticks(range(2009, 2020))

sns.lineplot(data=yearly_stats, x='Year', y='Reviews', hue='Genre', marker='o', ax=axes3[2], palette=color_palette)
sns.lineplot(data=overall_yearly, x='Year', y='Reviews', color='black', linestyle='--', label='Overall Avg', ax=axes3[2])
axes3[2].set_title("Average Review Count Trend (2009-2019)", fontsize=14, fontweight='bold')
axes3[2].set_ylabel("Review Count")
axes3[2].set_xticks(range(2009, 2020))
plt.tight_layout()
trends_img = fig_to_base64(fig3)

# 5. Top Authors
top_authors_counts = df['Author'].value_counts().head(10)
top_authors_list = top_authors_counts.index.tolist()
top_authors_data = df[df['Author'].isin(top_authors_list)]
author_stats = top_authors_data.groupby('Author').agg(
    Appearances=('Name', 'count'),
    Avg_Price=('Price', 'mean'),
    Avg_Rating=('User Rating', 'mean'),
    Genre=('Genre', lambda x: x.mode()[0])
).sort_values('Appearances', ascending=False).reset_index()

fig4, axes4 = plt.subplots(1, 2, figsize=(16, 6))
sns.barplot(data=author_stats, y='Author', x='Appearances', ax=axes4[0], hue='Genre', dodge=False, palette=color_palette)
axes4[0].set_title("Top 10 Authors by Appearances (2009-2019)", fontsize=12, fontweight='bold')
axes4[0].set_xlabel("Number of Appearances")
axes4[0].set_ylabel("")

sns.scatterplot(data=author_stats, x='Avg_Price', y='Avg_Rating', hue='Genre', size='Appearances', sizes=(100, 600), alpha=0.8, ax=axes4[1], palette=color_palette)
axes4[1].set_title("Top Authors: Average Price vs Rating", fontsize=12, fontweight='bold')
axes4[1].set_xlabel("Average Price ($)")
axes4[1].set_ylabel("Average Rating")

# Add labels for top authors on scatter plot
for i in range(author_stats.shape[0]):
    axes4[1].text(author_stats['Avg_Price'][i]+0.2, author_stats['Avg_Rating'][i], 
                  author_stats['Author'][i], horizontalalignment='left', 
                  size='small', color='black', weight='semibold')

plt.tight_layout()
authors_img = fig_to_base64(fig4)

